# Optional callback to adjust link order. This can be used to add, remove, or reorder objects.
# This is called once per module, with the module ID and the current link order.
#
# For example, this adds "dummy.c" to the end of the DOL link order if configured with --non-matching.
# "dummy.c" *must* be configured as a Matching (or Equivalent) object in order to be linked.
def link_order_callback(module_id: int, objects: List[str]) -> List[str]:
    # Don't modify the link order for matching builds
    if not config.non_matching:
        return objects
    if module_id == 0:  # DOL
        return objects + ["dummy.c"]
    return objects

# Uncomment to enable the link order callback.
# config.link_order_callback = link_order_callback

# Optional extra categories for progress tracking
# Adjust as desired for your project
config.progress_categories = [
    ProgressCategory("game", "Game Code"),
    ProgressCategory("sdk", "SDK Code"),
]
config.progress_each_module = args.verbose
# Optional extra arguments to `objdiff-cli report generate`
config.progress_report_args = [
    # Marks relocations as mismatching if the target value is different
    # Default is "functionRelocDiffs=none", which is most lenient
    # "--config functionRelocDiffs=data_value",
]

if args.mode == "configure":
    # Write build.ninja and objdiff.json
    generate_build(config)
    # ngccc synthesizes FP constant-pool entries (int->double cast magics)
    # into each object's .rodata, which would grow DOL section 7 and break
    # byte-identity. tools/fix_fp_pool.py retargets those relocs to the
    # matching lbl_* symbols already present in the DOL's .rodata2 and zeroes
    # the .rodata section, keeping every linked object text-only. The rule is
    # patched here so every fresh configure carries the fixup.
    _ninja = "build.ninja"
    if os.path.isfile(_ninja):
        _txt = open(_ninja).read()
        _old = ".sdata2 -R .sbss -R .sbss2 $out $out"
        _new = ".sdata2 -R .sbss -R .sbss2 $out $out && python3 tools/fix_fp_pool.py $out"
        if _old in _txt and "fix_fp_pool" not in _txt:
            _txt = _txt.replace(_old, _new)
            print("patched build.ninja: ngccc rule runs tools/fix_fp_pool.py")
        # Current mwcc omits trailing zero padding the original toolchain
        # emitted (15 SDK .data sections come up 1-7 bytes short of their
        # splits claims, shifting the link). tools/pad_sdk_data.py extends
        # those sections with zeros (no-op elsewhere). Patched here so every
        # fresh configure carries the fixup (same mechanism as fix_fp_pool).
        _old2 = "tools/transform_dep.py $basefile.d $basefile.d"
        _new2 = ("tools/transform_dep.py $basefile.d $basefile.d && $python "
                 "tools/pad_sdk_data.py $out")
        if _old2 in _txt and "pad_sdk_data" not in _txt:
            _txt = _txt.replace(_old2, _new2)
            print("patched build.ninja: mwcc rules run tools/pad_sdk_data.py")
        open(_ninja, "w").write(_txt)
elif args.mode == "progress":
    # Print progress information
    calculate_progress(config)
else:
    sys.exit("Unknown mode: " + args.mode)
